using System;namespace Recovered.Gameplay {public static class PtlMaterialTokens {public static void Refresh(SoundSetupImage m,uint material,Func<SoundSetupImage,uint,uint[],uint> external){Observe(m,material,external,null);}public static void Observe(SoundSetupImage m,uint material,Func<SoundSetupImage,uint,uint[],uint> external,Action<uint> tokenObserver){PtlPlatformLocks.Refresh(m,material,delegate(SoundSetupImage image,uint address,uint[] args){if(address==0x7416a0)return PtlProgramTokens.Observe(image,args[0],args[1],args[2],args[3],args[4],args[5],external,tokenObserver);return external(image,address,args);});}}}
